toad_implementation.code_blueprint:
canvas {
  size: 800px 920px;
  fill: #0E0C1A;
  font-family: "Sora, sans-serif";
}

>dusk = #0E0C1A;
>roseQuartz = #F687B3;
>sageMint = #6EE7B7;
>lavender = #A78BFA;
>etherealWhite = #FDFCFE;

circle #auraLayerLavender {
  at: center of canvas offset -40px -80px;
  size: 440px;
  fill: alpha(>lavender, 0.28);
}

circle #auraLayerRose {
  at: center of canvas offset 40px -60px;
  size: 400px;
  fill: alpha(>roseQuartz, 0.26);
}

circle #auraLayerMint {
  at: center of canvas offset 0px -40px;
  size: 320px;
  fill: alpha(>sageMint, 0.30);
}

circle #sphericalLens {
  at: center of canvas offset 0px -60px;
  size: 260px;
  fill: none;
  stroke: alpha(>etherealWhite, 0.25);
  stroke-width: 1px;
}

text #mantraTitle {
  at: below #auraLayerMint offset 72px;
  content: "P R E S E N C E";
  font-size: 24px;
  font-weight: 300;
  color: >etherealWhite;
}

text #mantraSub {
  at: below #mantraTitle offset 14px;
  content: "BREATHE IN DEEPLY • RESTORE BALANCE";
  font-size: 11px;
  font-weight: 500;
  color: >sageMint;
}
